cat node_modules/ajv/package.json | head -5; node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv();
for (const schema of [
  {type: 'object', required: 'location'},
  {type: 'object', properties: {location: {type: 'strng'}}},
  {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
]) {
  try { const v = ajv.compile(schema); console.log('compiled ok', JSON.stringify(schema), v({}) ); }
  catch (e) { console.log('THROWS:', JSON.stringify(schema), '->', e.message.split('\n')[0]); }
}
console.log('missing required validate:', ajv.compile({type:'object',properties:{location:{type:'string'}},required:['location']})({}).toString());
console.log('wrong type errors:', JSON.stringify(ajv.compile({type:'object',properties:{location:{type:'string'}},required:['location']})({location: 12345})));
console.log('extra prop errors:', JSON.stringify(ajv.compile({type:'object',properties:{location:{type:'string'}},required:['location']})({location:'Paris', extra: 'x'})));
console.log('enum errors:', JSON.stringify(ajv.compile({type:'object',properties:{units:{enum:['c','f']}}})({units:'k'})));
"
